---GetBattleEndTitle
---获取结算 Title
---@param passType number 关卡胜负
---@param questType Constants.IDType 关卡类型
function UIBattleEndTitle:GetBattleEndTitle()
    local questType = self.questType
    local passType = self.passType
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(self.questId)
    if questType == Constants.IDType.QuestTrail then
        return localize("到此为止")
    elseif questType == Constants.IDType.QuestMaze  then
        return localize("巡逻完成")
    elseif questType == Constants.IDType.QuestGachaCoin
            or questType == Constants.IDType.QuestGachaCoinChallenge then
        return localize("战斗胜利")
    elseif questType == Constants.IDType.QuestWorldBoss
            or questType == Constants.IDType.QuestNightCatBoss
            or questType == Constants.IDType.QuestMidFestivalBoss
            or questType == Constants.IDType.MournBoss
            or isNotNull(questVo) and isNotNull(questVo.isBossChallengeQuest) and (questVo.isBossChallengeQuest == true) then      -- 噩梦回响标记某一个关卡为boss挑战关卡，结算界面和世界boss一样
        return localize("战斗结束")
    elseif questType == Constants.IDType.QuestTrainField then
        return localize("训练结束")
    else
        return passType == 1 and localize("战斗胜利") or localize("战斗失败")
    end
end

---GetTitleBGSwitchState
---获取 Title BG 显示状态
---@param passType number 关卡胜负
---@param questType Constants.IDType 关卡类型
function UIBattleEndTitle:GetTitleBGSwitchState()
    local questType = self.questType
    local passType = self.passType
    if questType == Constants.IDType.QuestTrail
            or questType == Constants.IDType.QuestMaze
            or questType == Constants.IDType.QuestGachaCoin
            or questType == Constants.IDType.QuestGachaCoinChallenge then
        return 1
    else
        return passType == 1 and 1 or 2
    end
end

---GetQuestName
---获取副本命
---@param questId number
function UIBattleEndTitle:GetQuestName()
    local questId = self.questId
    local questVo = QuestConfMgr:GetInstance():GetQuestVoById(questId)
    local questName = isNull(questVo) and "" or questVo.name
    if isNull(questName) then
        questName = ""
    end
    local questType = GoodsUtils.GetIdType(questId, Constants.IDArea.Quests)
    if questType == Constants.IDType.QuestMain then
        questName = questVo.label .. " " .. questName
    end
    questName = string.gsub(questName, "\\n", "")
    return questName
end

